WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (290::BIGINT, 'El man tiene una maestría en administración de proyectos. Con eso le digo todo.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'a31dcef53c0925d1ce88d2248d7f6767cf57afd7fa706d341d330edd7d1788b2'::TEXT, ARRAY[2994]::BIGINT[]),
    (290::BIGINT, 'Es la única opción, consígase un proyecto bonito y que usted disfrute. Es un completo profe ausente, sube las varas de la semana cuando le da la gana, son miles de entregables y con rubricas que ni el entiende'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2026-08-04T00:00:00+00:00'::TIMESTAMPTZ, '571a3067acb328d958def4bfd3f32d362e646e7d181e866124ba69e11fb725e4'::TEXT, ARRAY[2994]::BIGINT[]),
    (290::BIGINT, 'Semana 4 y ya quiero que este curso se acabe'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2025-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'ae19cd14bcb4163642e76632e6ed5b67e74605638ac7e4ec3f77f5377ba9f973'::TEXT, ARRAY[2995, 2994]::BIGINT[]),
    (290::BIGINT, 'Ya expiró el man? Bretes pesados y largos cada p*ta semana'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2024-03-12T00:00:00+00:00'::TIMESTAMPTZ, 'f8c90815a90689ad1e763d16c6a3f76a77d0c4cceb2abfef1782ab25d2ec19f0'::TEXT, ARRAY[2995]::BIGINT[]),
    (290::BIGINT, 'exc profe, califica con lo que dice la rubrica. Hay que preguntarle cosas de fijo pero siempre ayuda y es muy buena gente. hay muchos quices, en general es muy ordenado pero si hay que ponerle mucho'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a311e16c10b13ff542dad468512764a7eeec3a9950ab307c3af7b0f764773202'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'El curso en si no es muy complicado, pero requiere mucho tiempo y un grupo de trabajo con el que se pueda coordinar bien. El profe en si es super pura vida y permite vacilar en clases mientras también se ve toda la materia y hace ejercicios divertidos para repasar la materia vista en clase sin nota.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Inspirador']::TEXT[], '2022-12-22T00:00:00+00:00'::TIMESTAMPTZ, '506b17d482a36f6f2844e602876568846ded20333d9aaeab3bf26dc4ea4e36ba'::TEXT, ARRAY[2970]::BIGINT[]),
    (290::BIGINT, 'Noguera para Datos I es un excelente profesor, creo que tiene un puntaje muy bajo en esta plataforma por comentarios viejos, pero definivitamente el no es lo que se describe en los comentarios viejos. Es excelente persona y las clases son muy entretenidas, ademas de que se aprende mucho.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2022-12-16T00:00:00+00:00'::TIMESTAMPTZ, '297bd051446db380ae3702004d07c3d3b726d214446557ba347681fa9a48f22d'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'La progra no es dificil pero si es larga, los examenes son respuesta multiple y ejercicios, los quices son la materia vista a ese dia, se pasa si se tiene un buen equipo de trabajo que entregue los proyectos'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-14T00:00:00+00:00'::TIMESTAMPTZ, '90c93b96110147cc904b2e76c93282d56650df34c8285a96be62783ea467e82a'::TEXT, ARRAY[2970]::BIGINT[]),
    (290::BIGINT, 'En semana 10 no tenía ni un solo entregable calificado, sube el enunciado de los entregables el día anterior. Brinda cero apoyo y sus clases son básicamente reutilizar material del profesor anterior. Si puede mejor no matricule con él y esperese al otro semestre.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-09-23T00:00:00+00:00'::TIMESTAMPTZ, 'f48dafab53db482343ac0c766f1c2993b16685a8390dfbef530bada2b5193c43'::TEXT, ARRAY[2995]::BIGINT[]),
    (290::BIGINT, 'Muy malo este profesor, se contradice mucho y siempre cree que tiene la razón. Los trabajos son confusos y con detalles no relevantes para lo que se está evaluando. No recomendado, si hay otra opción llévalo con ese'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '6bf1f230c9dc2d624648be9eef0790a0a12ed6ab5ce995427eace162a64c106c'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Muy buen profe, ayuda con las evaluaciones, si ve que usted le puso ganas al asunto, el le ayuda en la evaluación. Esperando poder llevar el curso otra vez con el'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '05561dcec54520b8f3908d2c933a79908f435c0eacb4083e85529779238fad5d'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'La clase es entretenida. Inicia con unos 20 minutos para hablar sobre temas externos al curso. Luego la clase se vuelve un poco rápida por eso, pero el profe explica bien la materia y hace actividades de práctica. El profe tarda en revisar asignaciones.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '16a9b4d4cd7b8a812526e49cf5c7eaea3a60bbfcede86579fbae4d9cc94ca00d'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Muy recomendado, las clases son cortas y siempre hace actividades para relajar la presión del semestre, eso si los proyectos son duros, vaya familiarizandose con C++. La nota general está modificada, no le hagan caso, lean el resto de evaluaciones hechas por los demás y van a ver que es buen profe.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '446206f780d6b31d1d97870abcbf5d65b9435e78de8afa6709efb8ba96cb4fa0'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Muy buen profe, hace las clases muy interactivas a pesar de ser virtuales, es exigente en la calidad de los trabajos pero con ser disciplinado y hacer las cosas a tiempo es suficiente. Si usted es indisciplinad@ y mediocre, no matricule aquí.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '9af203e5ae0c171c8b911238ee10507a468bcdedfe9a5827bff5dfa2f4c4a0c4'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'EXCELENTE profe. La clase es sumamente interactiva y divertida y se aprende muchísimo. Califica justo, es flexible y es muy claro en lo que pide y quiere. Las evaluaciones son muy accesibles, solo hay que prepararse bien. Como consejo para los proyectos un buen grupo ayuda bastante. 11/10 como profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '8c1c78de32c531fa967c862aec4742c8b68ba0049843710f74907454a1731ef1'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Excelente profesor, está lleno de malos comentarios pero creo que es porque ha mejorado durante los años. Clases súper entretenidas, hace kahoots de repaso, ayuda si usted le hace consultas, es muy atento y me sorprendió lo ordenado que es, no falla con los correos y los mensajes informando.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'a7aaeb2a54d06348e78300735a710bd6de584ee653a358c6186c491bd05ab123'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'El mejor profe de progra que he tenido, es estricto, pero explica super bien y las clases no se hacen pesadas. Aunque sea estricto es comprensivo y está dispuesto a ayudar. Con el se aprende bastante, lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, '6a3b5a23720277787e59c26eb396eba714fa7408665621112dd5be9122c2348e'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Sin dudas es un excelente profesor. Deja la materia sumamente clara y está muy abierto a dudas. Sus quices son acordes a lo que explica. A veces es poco profesional y se excusa en que "el mercado es así", pero definitivamente es la mejor opción para Datos I y II.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2021-04-17T00:00:00+00:00'::TIMESTAMPTZ, 'ede207a54116b1114b8abb72ad27da79c79117b44221ba6ca931d95dcea4e74f'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Es un excelente profesor y persona, no se porque tiene una nota tan baja. Siempre esta dispuesto a sacar dudas y es muy respetuoso. No le tenga miedo si necesita mas tiempo para progras, pidaselo y el dara mas chance. Sin duda un excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '4ed7a5eb045c552827c3cc93ef7b0a4c14861c606ff8f5462360ff63175256f0'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'Simplemente excepcional. Un profesor excelente en todo el sentido de la palabra. Si va a llevarlo con él tenga claro que va a tener que trabajar un montón, y pulir bien su trabajo, tanto las progras como los diagramas que piden. Piensa mucho en los estudiantes, pero no esperen que les regale nada.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '4ad1c665c20e58933972585c6889d9843e9146bb16ac9a63ad46f5766a303348'::TEXT, ARRAY[2970]::BIGINT[]),
    (290::BIGINT, 'No le tenga miedo, virtualmente es un amor de profe. Explica todo súper claro y siempre está atento por consultas. En mi caso revisó las progras muy suave. Pero como todo curso, si hay que poner de su cuenta y trabajar bastante. Pero el profe hace el curso bastante llevable'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '8ab1bd61d5ddcf56893654631b84944b945340f5b8af23e32dca19e41375b0d4'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Es buena persona, se lleva con los estudiantes y cuando es hora de vacilar se la pasa bien. Como profe es buenillo, siento que por la extensión del curso todo se ve muy rápido y casi que no da tiempo de nada, pero explica bien. Da puntos extra en progras si las hace bien'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '50e53ea94a710ed9a8b409dd0f70ab9758b0217f4d094888a1383f4be7c58490'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Bastante estricto en tareas y clases, si usted es de los que le pone la clase es llevadera y si le va mal el profe reconoce su esfuerzo, no se pasa fácil pero tampoco es tan difícil como lo ponen'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '8e4c32698841fecba224a63608a584a8b50ad8096b5d0329a1a596016c40d666'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Es buen profe y sabe mucho, pero quita puntos de donde no hay, trate de conseguir las rúbricas de las evaluaciones desde antes. Tiene cambios de humor, puede que lo trate bien o muy mal.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'e4927c560c30087bfef72e45f62c7253eb2f9806bd01f0fa7fd3911eb80e18b8'::TEXT, ARRAY[2964]::BIGINT[]),
    (290::BIGINT, 'Totalmente recomendado, se aprende mucho con él, pero es muy estricto con las evaluaciones y tareas morales, si usted le pone le ayuda bastante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '35bf48c7b137c3e6f380b7c5c8d520baf06ca4d93277602ba725d34c46823364'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Honestamente no se porque hay tantos comentarios negativos si Noguera es un excelente profesor, si usted le pone en el curso va a ver que el profesor no va a dudar en ayudarlo, se termina aprendiendo un montón con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '28d8d3db45c9ad1d051b0a6c0fbe5b265e81c2189648edb6938eee1ebf90c741'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Los proyectos no tienen relación con lo que se ve en clase y tras de eso los califica duros y valen 60% de la nota. Hace muchas preguntas en clase'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'add4e1d2f4870541c83fe7e8878e5096b39ef6549740d9419d590eebd831782a'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2019-12-14T00:00:00+00:00'::TIMESTAMPTZ, '2b1b3fd841b2e2febe81e1507be2429b72b6882aef2f4d7b18b83c86e35fe3e3'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'Es un profe duro, pero es porque en serio tiene interés en que el estudiante aprenda. Aprecia el esfuerzo constante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '6f7213fcd0f8c8add0c127c86d3195cf9a372cbeb7f150b732a3ffe0e532ceb1'::TEXT, ARRAY[2964]::BIGINT[]),
    (290::BIGINT, 'Es un profe difícil, pero justo, da puntos extra si ve que usted se esforzó en lo que hace y deja muchas enseñanzas para la vida. Sin embargo está en muchas varas y de tantas cosas que está metido se desordena increiblemente y eso puede llegar a molestar mucho.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '2179ceadc84d99cca01e9996c58f1367afb7741b798e2d3dd74760a42ee2211b'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'Las clases suelen ser muy dinámicas y entretenidas, un profesor con pasión por los contenidos que enseña.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Inspirador']::TEXT[], '2019-02-27T00:00:00+00:00'::TIMESTAMPTZ, 'a0bb4e5ef7ef1d5e73e36047983cd18892b634391d2484d4aaff6ecc272e43ab'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Exige bastante pero se compensa con la calidad de enseñanza y con el esfuerzo que usted le dedique al curso, suele hacer la clase interactiva y deja bastantes tareas morales las cuales se traducen en puntos extra al final del semestre. El aprendizaje no se limita a los contenidos del curso :D'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'd8f8bc51833f99f58d548d0e57c3b20dfa832a3e56db1fb20b0a75fee2053cf6'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'No enseña ni la mitad de lo que enseña el otro profesor. Los puntos extra se los guarda para datos 1 y 2. Califica casi binario. Si tiene que llevarlo con el prepárese para un curso de asistencia obligatoria donde hay que ir a escuchar leer las diapositivas del otro profesor...'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '8718240d0028854f3440c9447c138292348f49c0e8c57ddbf7d71c51ed9430f3'::TEXT, ARRAY[2964]::BIGINT[]),
    (290::BIGINT, 'Explica muy bien la materia, califica los entregables suuuuper duro, dedíquele bastante tiempo porque el curso es muy demandante. Da mucha retroalimentación y es muy pura vida.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '73a4d3d7f92bf101a289526730e12187fa48ced34780d0865e6a507eb53530c8'::TEXT, ARRAY[2964]::BIGINT[]),
    (290::BIGINT, 'La pura leche'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2018-10-27T00:00:00+00:00'::TIMESTAMPTZ, '36de7c237b17615fcc2deb791de72f03a9ba97271b60f87712fb111fceca9e22'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'Excelente profesor, explica muy bien, buenos ejemplos. Da puntos extra por las tareas morales. Califica duro. Recomiendo estudiar para los quices.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2018-10-20T00:00:00+00:00'::TIMESTAMPTZ, '5b1d3a6400f02a6b3f68c7ba65e1d6ce0a78b95c9d83b1b7b94bd0c931accc2d'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Excelente profesor, es muy bueno explicando y ayuda bastante, califica duro, pero se aprende bastante con él'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a9030c841ee343598a31c3fd7e01128849c74b9e7e1a40069bf1ffb49fd3b3f0'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Es muy exigente, pero de verdad se aprende, eso si tiene que dedicarle bastante tiempo al curso, deja tareas morales y da puntos extra al final de semestre por las tareas realizadas'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd62f46d5a9eb3e091dac0363e6832122745bbd1dc39097a2792597e644f16eee'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Véalo así, el mae es bien exigente. Revisa las progras de manera ruda. Deja bastantillas tareas morales y dependiendo de su desempeño en estas es la ayuda (puntos extra) de parte de él al final del semestre. Sin embargo, es muy buen profe y se aprende muchísimo con él.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2018-01-12T00:00:00+00:00'::TIMESTAMPTZ, '2de5b33b3af6e9f7d0efb14e4bb26251e5075952fa75d4a5baf29777a6b38a59'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'Es muy pura vida con sus estudiantes, la dificultad es, que no usa código para explicar casi nada, si lo muestra será solo eso, no lo explica mucho, recomiendo que sepa java de una vez (eso facilita POO). Estudien antes de los quices. El dashboard no es jugando, hágalo desde que pueda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-24T00:00:00+00:00'::TIMESTAMPTZ, '48a73530e12cb0d7f42ed1dbce831003b940cd59f8cf6e0d53b7b076c38fbccc'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'El profe es muy pura vida, explica bien, califica muy duro, si usted le pone le ayuda.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e3b4fec95b64f9cd5523a829a1b41d62a36aaa568008decacf441d7bbac87869'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bfe50f1f175cdbf46bb6c0fb2a8db5c86c3581df7170dcd0d648ca8f617edddf'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'El curso es duro y no sabe nada. Pero si hace los puntos adicionales el mae hace curva con eso. Cuando lleve el curso regalo 10 puntos adicionales y si uno no ocupaba los puntos adicionales para pasar regalaba otros 5, eso ayuda un montón en el ponderado.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f4c1173483f793ea848a89b0599ba3432979178c642652d87336af980e2f8ef4'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Sumamente bueno, si le pone desde el principio y pone buenos proyectos el le ayuda bastante, recomendado'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-02T00:00:00+00:00'::TIMESTAMPTZ, '3245db8cbb30d1d822a6c132679bb102d15be83838265df93a5499506d8b2a7b'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Ayuda montones si le pone'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-02T00:00:00+00:00'::TIMESTAMPTZ, '76f768f1aa84f9073cfb0ada141dbbf4eeff91134ef14cbc422a99bba1718970'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, '424c712a9f026464bbd4861a845ebb3def7200ed973458a8b746db07f685c4ae'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'La primera mitad del semestre llego tarde, trabaja en hp y le queda largo el vieja, casi siempre 15 min tarde. Cuando se tuvo que ausentar por una semana la repuso antes, es decir muy responsable con la clase a pesar de llegar tarde. Si ud entrega un trabajo bien completo puede que le regale puntos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'cdf88d786bf9ebcbffbd85a2297b4aabec779b452becfd4b5b78a43ff43b1d6a'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Explica muy bien y con claridad los temas, los quices son fáciles si se lee por lo menos la materia un día antes, califica muy duro y cuesta que le ayude con consultas fuera de la clase, así que pregunten en la misma'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'b6a84c9d88315a3e5b17d63ceed1a272817e42545b1f61b67dd48ab4c38ec46e'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'd6979579d66dfabfcbce8600f33e00fcb466cc922e8befd8a73dcaa933772a9f'::TEXT, ARRAY[2962]::BIGINT[]),
    (290::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-11-11T00:00:00+00:00'::TIMESTAMPTZ, '0db9848bd7e996021b453e407feb62e3d0a706522584310207ba5aae20c83e38'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Este profe confunde computación con computadores, exige como si lo único que se hiciera fuera estar en su clase. No lo recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2016-11-07T00:00:00+00:00'::TIMESTAMPTZ, '45aa105cf320451db30f4dd2a652faba6b3d8187ee9e3fbbf80eb0d99afa449b'::TEXT, ARRAY[2965]::BIGINT[]),
    (290::BIGINT, 'Explica muy bien, se aprende bastante, es super exigente, califíca durísimo, es una teja como persona.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Inspirador']::TEXT[], '2016-10-29T00:00:00+00:00'::TIMESTAMPTZ, '1827435b51854cc49a14579ce87d751c8145fc61d70363b1669161f0a081d381'::TEXT, ARRAY[2962, 2965]::BIGINT[]),
    (290::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Brinda apoyo']::TEXT[], '2016-10-28T00:00:00+00:00'::TIMESTAMPTZ, '10c311bbdb396e97af1cd49abc34a17ff9ae209e89be23fe6d847550f1313f03'::TEXT, ARRAY[2965]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
